#!/usr/bin/env bash
# Question 1: Pod ${Q1_CLAIM}-app stuck. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl label node worker-1 "storage.cka.lab/${Q1_CLAIM}=data" --overwrite >/dev/null
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q1_CLAIM}-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q1_CLAIM}
    type: DirectoryOrCreate
  nodeAffinity:
    required:
      nodeSelectorTerms:
        - matchExpressions:
            - { key: storage.cka.lab/${Q1_CLAIM}, operator: In, values: [data] }
EOF
# Faults append shell assignments here (sc=..., pin=...); after reads them back. A file rather than
# shell variables, because a layered question runs every fault in its own subshell.
: > "/var/tmp/cka-q1.claim"

case "${Q1_FAULT}" in
  storageclass-mismatch)
    echo 'sc=fast' >> "/var/tmp/cka-q1.claim"
    ;;
  access-mode-mismatch)
    echo 'mode=ReadWriteMany' >> "/var/tmp/cka-q1.claim"
    ;;
  claim-too-large)
    echo 'size=2Gi' >> "/var/tmp/cka-q1.claim"
    ;;
  pv-released-claimref)
    kubectl apply -f - <<< '{"apiVersion":"v1","kind":"List","items":[{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"${Q1_CLAIM}"'","namespace":"'"${Q1_NS}"'"},"spec":{"storageClassName":"manual","accessModes":["ReadWriteOnce"],"resources":{"requests":{"storage":"500Mi"}}}},{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q1_CLAIM}"'-app","namespace":"'"${Q1_NS}"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}]}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"${Q1_CLAIM}"'"}}]}}]}'
    kubectl -n "${Q1_NS}" wait --for=jsonpath='{.status.phase}'=Bound "pvc/${Q1_CLAIM}" --timeout=60s
    kubectl -n "${Q1_NS}" delete pod "${Q1_CLAIM}-app" --wait=true
    kubectl -n "${Q1_NS}" delete pvc "${Q1_CLAIM}" --wait=true
    for _ in $(seq 1 30); do
      [[ "$(kubectl get pv "${Q1_CLAIM}-pv" -o jsonpath='{.status.phase}')" == Released ]] && break
      sleep 1
    done
    [[ "$(kubectl get pv "${Q1_CLAIM}-pv" -o jsonpath='{.status.phase}')" == Released ]] || { echo "PV is not Released" >&2; exit 1; }
    ;;
  pod-node-pin)
    echo 'pin=worker-2' >> "/var/tmp/cka-q1.claim"
    ;;
  pv-node-label-lost)
    kubectl label node worker-1 "storage.cka.lab/${Q1_CLAIM}-" >/dev/null
    ;;
  pod-claim-name)
    echo 'podclaim=${Q1_CLAIM}-data' >> "/var/tmp/cka-q1.claim"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

sc=manual mode=ReadWriteOnce size=500Mi pin= podclaim="${Q1_CLAIM}"
. "/var/tmp/cka-q1.claim"
sel=''
[[ -z "$pin" ]] || sel=',"nodeSelector":{"kubernetes.io/hostname":"'"$pin"'"}'
kubectl apply -f - <<< '{"apiVersion":"v1","kind":"List","items":[{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"${Q1_CLAIM}"'","namespace":"'"${Q1_NS}"'"},"spec":{"storageClassName":"'"$sc"'","accessModes":["'"$mode"'"],"resources":{"requests":{"storage":"'"$size"'"}}}},{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q1_CLAIM}"'-app","namespace":"'"${Q1_NS}"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}]}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"$podclaim"'"}}]'"$sel"'}}]}'
sleep 10
[[ "$(kubectl -n "${Q1_NS}" get pod "${Q1_CLAIM}-app" -o jsonpath='{.status.phase}')" == Pending ]] || { echo "${Q1_CLAIM}-app is not Pending" >&2; exit 1; }
